// Skill keystone node art (pixel conversion, 2026-11-07): the
// 30x30 texel node grids and their composer, moved out of the
// component file so the lint test verifies the shipped art
// without importing a component module.

export type KeystoneNodeType = 'small' | 'major' | 'keystone';

