const GRID = 30;

/**
 * Compose the full node render (glow + shape + marks) as one grid —
 * the exact cell data the canvas paints, exported so the lint test
 * verifies the shipped art, not a copy of it. The tree sigil and the
 * lock mark are PX_ICONS rect data composited at paint time (they
 * were embedded icon data in the SVG too) and are not part of this
 * grid.
 */
export function buildKeystoneGrid(
  nodeType: KeystoneNodeType,
  unlocked: boolean,
): { rows: string[]; glowRows: string[] } {
  let glowRows: string[] = Array.from({ length: GRID }, () => '.'.repeat(GRID));
  if (unlocked) {
    glowRows = glowRows.map((row, y) =>
      row
        .split('')
        .map((_, x) => {
          const d = Math.hypot(x - 14.5, y - 14.5);
          if (d <= 7.5) return 'G';
          if (d <= 10.5) return 'g';
          if (d <= 13) return 'h';
          return '.';
        })
        .join(''),
    );
  }
  const grid = KEYSTONE_NODE_GRIDS[nodeType].map((r) => r.split(''));
  const put = (x: number, y: number, key: string) => {
    grid[y][x] = key;
  };
  if (nodeType === 'small') {
    // Center dot (was an r=3 circle at the 60-box center).
    put(14, 14, 'A'); put(15, 14, 'A'); put(14, 15, 'A'); put(15, 15, 'A');
  } else if (nodeType === 'major') {
    // Center cross (was two 2-wide lines, 22..38 in the 60-box).
    for (let i = 11; i <= 18; i++) {
      put(15, i, 'A');
      put(i, 15, 'A');
    }
  } else {
    // Radiating ticks: the stub cells adjacent to the star's points
    // take the accent (was two short accent lines over the stubs).
    put(15, 3, 'T');
    put(15, 26, 'T');
  }
  return { rows: grid.map((r) => r.join('')), glowRows };
}
